import json, sys
from datetime import datetime, timezone


def parse_dt(s):
    """Parse an ISO8601 string into an offset-aware UTC datetime.
    Returns None for non-strings, missing/null, or naive (no offset)."""
    if not isinstance(s, str):
        return None
    ss = s.strip().replace('Z', '+00:00')
    try:
        dt = datetime.fromisoformat(ss)
    except ValueError:
        return None
    if dt.tzinfo is None:
        return None  # naive -> skip
    return dt.astimezone(timezone.utc)


data = json.load(open(sys.argv[1]))
as_of = parse_dt(data["as_of"])

result = []
for r in data.get("reminders", []):
    if r.get("completed"):
        continue
    dt_due = parse_dt(r.get("due"))
    if dt_due is None:
        continue
    if dt_due <= as_of:
        result.append((dt_due, r["id"], r["title"], dt_due.strftime("%Y-%m-%dT%H:%M:%SZ")))

result.sort(key=lambda x: (x[0], x[1]))
out = [{"id": i, "title": t, "due_utc": d} for (dt_, i, t, d) in result]
print(json.dumps(out))
